def is_in_G(n):
    # Check if n = 11a + 20b for non-negative integers a, b
    if n < 0:
        return False
    for b in range(n // 20 + 1):
        remainder = n - 20 * b
        if remainder >= 0 and remainder % 11 == 0:
            return True
    return False

print("Testing small numbers:")
for i in range(0, 100):
    if i not in [0, 11, 20, 22, 31, 33, 40, 42]: # Known elements <= 42
        if not is_in_G(i):
            print(f"{i}: NOT in G")
        else:
            print(f"{i}: In G")

# Check the non-G element m=9
print(f"9: {is_in_G(9)}")
# Check the sequence generated by 9: 29
print(f"29: {is_in_G(29)}")
# Check the sequence generated by 29: 49
print(f"49: {is_in_G(49)}")
